import sys, io, json, glob, os, contextlib
from meterbill import cli
out = []
def run(argv):
    o, e = io.StringIO(), io.StringIO()
    try:
        with contextlib.redirect_stdout(o), contextlib.redirect_stderr(e):
            code = cli.main(argv)
    except SystemExit as x:
        code = x.code
    except Exception as x:
        code = 'EXC ' + type(x).__name__
