"""meterbill.money: the one place where amounts are rounded."""

import ast
import math
import unittest
from decimal import Decimal
from pathlib import Path

from meterbill import cash, money, standing


def D(s: str) -> Decimal:
    return Decimal(s)


class RoundAmount(unittest.TestCase):
    def test_ties(self):
        self.assertEqual(money.round_amount(D("0.125"), money.CENT, money.HALF_UP), D("0.13"))
        self.assertEqual(money.round_amount(D("0.125"), money.CENT, money.HALF_EVEN), D("0.12"))
        self.assertEqual(money.round_amount(D("0.135"), money.CENT, money.HALF_EVEN), D("0.14"))
        self.assertEqual(money.round_amount(D("-0.125"), money.CENT, money.HALF_UP), D("-0.13"))
        self.assertEqual(money.round_amount(D("-0.129"), money.CENT, money.DOWN), D("-0.12"))

    def test_even_multiple_of_the_step(self):
        step = D("0.05")
        self.assertEqual(money.round_amount(D("0.125"), step, money.HALF_EVEN), D("0.10"))
        self.assertEqual(money.round_amount(D("0.175"), step, money.HALF_EVEN), D("0.20"))
        self.assertEqual(money.round_amount(D("0.125"), step, money.HALF_UP), D("0.15"))

    def test_exponent_of_the_step(self):
        self.assertEqual(str(money.round_amount(D("7"), D("0.05"), money.HALF_UP)), "7.00")
        self.assertEqual(str(money.round_amount(D("7.4"), D("1"), money.HALF_UP)), "7")
        self.assertEqual(str(money.round_amount(D("7.45"), D("0.10"), money.HALF_UP)), "7.50")
        self.assertEqual(str(money.round_amount(D("-0.001"), money.CENT, money.HALF_UP)), "-0.00")

    def test_large_values_are_exact(self):
        big = D("123456789012345678901234567890.125")
        self.assertEqual(money.round_amount(big, money.CENT, money.HALF_UP), D("123456789012345678901234567890.13"))

    def test_errors(self):
        with self.assertRaises(TypeError):
            money.round_amount(1.5, money.CENT, money.HALF_UP)
        with self.assertRaises(TypeError):
            money.round_amount(D("1"), 0.01, money.HALF_UP)
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), money.CENT, "up")
        for bad in (D("0"), D("-0.01")):
            with self.assertRaises(ValueError):
                money.round_amount(D("1"), bad, money.HALF_UP)


class Allocate(unittest.TestCase):
    def test_sums_to_the_rounded_whole(self):
        amounts = [D("5.3469"), D("7.8966")]
        parts = money.allocate(amounts, money.CENT)
        self.assertEqual(parts, [D("5.34"), D("7.90")])
        self.assertEqual(sum(parts), money.round_amount(sum(amounts), money.CENT, money.HALF_UP))

    def test_other_steps_and_unchanged_input(self):
        amounts = [D("1.07"), D("2.07"), D("0")]
        copy = list(amounts)
        parts = money.allocate(amounts, D("0.05"))
        self.assertEqual(amounts, copy)
        self.assertEqual(parts, [D("1.05"), D("2.10"), D("0.00")])
        self.assertEqual(sum(parts), money.round_amount(D("3.14"), D("0.05"), money.HALF_UP))

    def test_empty(self):
        self.assertEqual(money.allocate([], money.CENT), [])

    def test_standing_uses_it(self):
        self.assertEqual(standing.prorate([]), [])


class LegacyCents(unittest.TestCase):
    def test_binary_floating_point(self):
        for x in (1.005, 2.675, -0.005, 0.125, -4.25, 123456.785):
            self.assertEqual(money.legacy_cents(x), math.floor(x * 100 + 0.5) / 100)
        self.assertEqual(money.legacy_cents(1.005), 1.0)
        self.assertEqual(money.legacy_cents(0.125, 1), 0.1)
        self.assertEqual(money.legacy_cents(2.5, 0), 3.0)
        self.assertEqual(money.legacy_cents(1.2345675, 6), math.floor(1.2345675 * 10**6 + 0.5) / 10**6)


class Fixed(unittest.TestCase):
    def test_float(self):
        self.assertEqual(money.fixed(0.125, 2), "0.12")
        self.assertEqual(money.fixed(2.675, 2), "2.67")
        self.assertEqual(money.fixed(3.5, 0), "4")
        self.assertEqual(money.fixed(-0.001, 2), "-0.00")
        with self.assertRaises(ValueError):
            money.fixed(0.5, 2, money.HALF_UP)

    def test_decimal(self):
        self.assertEqual(money.fixed(D("0.125"), 2, money.HALF_UP), "0.13")
        self.assertEqual(money.fixed(D("0.125"), 2), "0.12")
        self.assertEqual(money.fixed(D("12.5"), 0, money.HALF_UP), "13")
        self.assertEqual(money.fixed(D("1E+3"), 1), "1000.0")
        self.assertEqual(money.fixed(D("1E-9"), 4), "0.0000")
        self.assertEqual(money.fixed(D("-12.99"), 1, money.DOWN), "-12.9")


class Callers(unittest.TestCase):
    def test_cash(self):
        self.assertEqual(str(cash.payable(D("12.33"), "0.05")), "12.35")
        self.assertEqual(str(cash.payable(D("-0.4"), "whole")), "0")
        self.assertEqual(str(cash.payable(D("-0.01"), "0.05")), "-0.00")
        self.assertEqual(str(cash.payable(D("2.5"), "whole")), "2")


class OnlyMoneyRounds(unittest.TestCase):
    FORBIDDEN_CALLS = {"round", "floor", "ceil", "trunc", "quantize", "to_integral", "to_integral_value", "to_integral_exact", "getcontext", "setcontext", "localcontext"}

    def test_sources(self):
        for path in sorted(Path(money.__file__).parent.glob("*.py")):
            tree = ast.parse(path.read_text(encoding="utf-8"))
            for node in ast.walk(tree):
                if isinstance(node, ast.Name):
                    self.assertNotIn(node.id, {"getcontext", "setcontext", "localcontext", "DefaultContext", "BasicContext", "ExtendedContext"}, path.name)
                if path.name == "money.py":
                    continue
                if isinstance(node, ast.Call):
                    f = node.func
                    name = f.id if isinstance(f, ast.Name) else f.attr if isinstance(f, ast.Attribute) else ""
                    self.assertNotIn(name, self.FORBIDDEN_CALLS, path.name)
                if isinstance(node, ast.FormattedValue) and node.format_spec is not None:
                    spec = ast.unparse(node.format_spec)
                    self.assertNotIn(".", spec.replace("{", "").split("}")[0], f"{path.name}: {spec}")
                if isinstance(node, ast.Name) and node.id.startswith("ROUND_"):
                    self.fail(f"{path.name} names {node.id}")


if __name__ == "__main__":
    unittest.main()
